include '../includes/session.php';include '../database/config.php';include '../includes/helpers.php';require_once '../services/SacramentalCsvImportService.php';requireAdmin();requirePermission('records.manage');
$service=new SacramentalCsvImportService($conn,dirname(__DIR__));$actor=(int)$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){requireValidCsrfToken();try{if(($_POST['action']??'')==='stage'){$id=$service->stage((string)($_POST['record_type']??''),$_FILES['csv']??[],$actor);redirectWithNotification('?id='.$id,'CSV validated. Review the result before confirming.','success');}if(($_POST['action']??'')==='confirm'){$count=$service->confirm((int)$_POST['import_id'],$actor);redirectWithNotification('?id='.(int)$_POST['import_id'],$count.' records imported.','success');}throw new DomainException('Invalid action.');}catch(Throwable$e){redirectWithNotification('sacramental-import.php'.(!empty($_POST['import_id'])?'?id='.(int)$_POST['import_id']:''),$e->getMessage(),'error');}}
$batch=null;if(!empty($_GET['id']))try{$batch=$service->batch((int)$_GET['id'],$actor);}catch(Throwable$e){redirectWithNotification('sacramental-import.php',$e->getMessage(),'error');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Validated CSV import</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/css/holy-theme.css"></head><body><?php include '../includes/admin-sidebar.php';?><main class="admin-content p-4" style="margin-left:280px"><h1>Validated sacramental CSV import</h1><p class="text-muted">Upload UTF-8 CSV (maximum 2 MB / 5,000 rows). Nothing is inserted until validation passes and you confirm.</p><div class="card card-body mb-4"><form method="post" enctype="multipart/form-data" class="row g-3"><?php echo csrfInput();?><input type="hidden" name="action" value="stage"><div class="col-md-4"><label class="form-label">Record type</label><select class="form-select" name="record_type"><?php foreach(SacramentalRecordService::types() as$t):?><option value="<?php echo e($t);?>"><?php echo e(ucfirst($t));?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">CSV file</label><input class="form-control" type="file" name="csv" accept=".csv,text/csv" required></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Validate</button></div></form></div>
<?php if($batch):?><div class="card"><div class="card-header d-flex justify-content-between"><span><?php echo e($batch['original_name']);?> — <?php echo e($batch['status']);?></span><span><?php echo(int)$batch['valid_rows'];?> valid / <?php echo(int)$batch['invalid_rows'];?> invalid</span></div><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Row</th><th>Status</th><th>Errors</th><th>Data</th></tr></thead><tbody><?php foreach($batch['rows'] as$r):?><tr class="<?php echo $r['validation_status']==='valid'?'':'table-danger';?>"><td><?php echo(int)$r['row_number'];?></td><td><?php echo e($r['validation_status']);?></td><td><?php echo e(implode('; ',json_decode($r['errors_json'],true)?:[]));?></td><td><code><?php echo e($r['row_data']);?></code></td></tr><?php endforeach;?></tbody></table></div><div class="card-body"><a class="btn btn-outline-secondary" href="sacramental-import-errors.php?id=<?php echo(int)$batch['import_id'];?>">Download error report</a><?php if($batch['status']==='preview'&&(int)$batch['invalid_rows']===0):?><form method="post" class="d-inline" onsubmit="return confirm('Import all validated rows into the official registry?');"><?php echo csrfInput();?><input type="hidden" name="action" value="confirm"><input type="hidden" name="import_id" value="<?php echo(int)$batch['import_id'];?>"><button class="btn btn-success">Confirm import</button></form><?php endif;?></div></div><?php endif;?></main></body></html>
